package com.hbm.machine.reactor.rbmk.core;
import java.util.*;import com.hbm.machine.reactor.rbmk.RbmkDials;import com.hbm.radiation.HbmRadiation;import net.minecraft.core.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.Level;import net.minecraft.world.phys.Vec3;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.event.level.LevelEvent;import net.neoforged.neoforge.event.server.ServerStoppedEvent;import net.neoforged.neoforge.event.tick.ServerTickEvent;
/** Actual NeutronHandler/NeutronNodeWorld/RBMKNeutronHandler, with source operation order and cache quirks. No column is registered by this library. */
public final class RbmkNeutronField {
 private static final Map<ServerLevel,Field> WORLDS=new HashMap<>();private static final Direction[] DIRECTIONS={Direction.NORTH,Direction.EAST,Direction.SOUTH,Direction.WEST};private static int ticks;private static boolean registered;private static double moderatorEfficiency,reflectorEfficiency,absorberEfficiency;private static int columnHeight,fluxRange;
 public static void register(){if(registered)return;registered=true;NeoForge.EVENT_BUS.addListener(RbmkNeutronField::beforeServerTick);NeoForge.EVENT_BUS.addListener((LevelEvent.Unload event)->{if(event.getLevel() instanceof ServerLevel world)WORLDS.remove(world);});NeoForge.EVENT_BUS.addListener((ServerStoppedEvent event)->{WORLDS.clear();ticks=0;});}
 private static void beforeServerTick(ServerTickEvent.Pre event){boolean clean=ticks>=20;if(clean)ticks=0;ticks++;WORLDS.values().removeIf(field->field.streams.isEmpty());for(var entry:WORLDS.entrySet()){var world=entry.getKey();var field=entry.getValue();reflectorEfficiency=RbmkDials.getReflectorEfficiency(world);absorberEfficiency=RbmkDials.getAbsorberEfficiency(world);moderatorEfficiency=RbmkDials.getModeratorEfficiency(world);columnHeight=RbmkDials.getColumnHeight(world)+1;fluxRange=RbmkDials.getFluxRange(world);for(var stream:field.streams)stream.run(world,field);field.streams.clear();if(clean)field.clean();}}
 private static Field field(ServerLevel world){return WORLDS.computeIfAbsent(world,ignored->new Field());}private static RbmkFluxColumn column(ServerLevel world,BlockPos pos){return world.hasChunkAt(pos)&&world.getBlockEntity(pos) instanceof RbmkFluxColumn column?column:null;}
 public static void remove(Level world,BlockPos pos){if(world instanceof ServerLevel server){var field=WORLDS.get(server);if(field!=null)field.nodes.remove(pos);}}
 public static void lid(Level world,BlockPos pos,boolean lid){if(world instanceof ServerLevel server){var field=WORLDS.get(server);if(field!=null){var node=field.nodes.get(pos);if(node!=null)node.lid=lid;}}}
 public static void spread(ServerLevel world,RbmkFluxColumn.Fuel fuel,double flux,double ratio){var pos=fuel.entity().getBlockPos();if(flux==0){remove(world,pos);return;}var field=field(world);var node=make(field,fuel);field.nodes.put(node.pos,node);if(fuel.reasimFuel()){var vector=rotate(new Vec3(1,0,0),world.random.nextInt(4)*9D);for(int i=0;i<8;i++){field.streams.add(new Stream(node,vector,flux*.75,ratio));vector=rotate(vector,45D);}}else for(var direction:DIRECTIONS)field.streams.add(new Stream(node,new Vec3(direction.getStepX(),0,direction.getStepZ()),flux,ratio));}
 private static Vec3 rotate(Vec3 vector,double degrees){double radians=degrees/180D*Math.PI,cos=Math.cos(radians),sin=Math.sin(radians);return new Vec3(vector.x*cos+vector.z*sin,vector.y,vector.z*cos-vector.x*sin);}
 private static Node make(Field field,RbmkFluxColumn column){var node=field.nodes.get(column.entity().getBlockPos());return node!=null?node:new Node(column);}
 private static final class Field{final List<Stream> streams=new ArrayList<>();final Map<BlockPos,Node> nodes=new HashMap<>();void clean(){var remove=new ArrayList<BlockPos>();for(var node:nodes.values())remove.addAll(node.check(this));for(var pos:remove)nodes.remove(pos);}}
 private static final class Node{final RbmkFluxColumn column;final BlockPos pos;final RbmkFluxColumn.Type type;boolean lid;Node(RbmkFluxColumn column){this.column=column;pos=column.entity().getBlockPos().immutable();type=column.neutronType();lid=column.hasLid();}
  private Iterator<BlockPos> reasimNodes(){return new Iterator<>(){int x=-fluxRange,z=-fluxRange;@Override public boolean hasNext(){return(fluxRange+x)*(fluxRange*2+1)+z+fluxRange+1<(fluxRange*2+1)*(fluxRange*2+1);}@Override public BlockPos next(){boolean inside=Math.pow(x,2)+Math.pow(z,2)<=fluxRange*fluxRange;z++;if(z>fluxRange){z=-fluxRange;x++;}return inside?pos.offset(x,0,z):null;}};}
  List<BlockPos> check(Field field){var remove=new ArrayList<BlockPos>();var streams=new ArrayList<Stream>();for(var dir:DIRECTIONS)streams.add(new Stream(this,new Vec3(dir.getStepX(),0,dir.getStepZ()),0,0));if(column instanceof RbmkFluxColumn.Fuel fuel&&!fuel.reasimFuel()&&(!fuel.hasFuelRod()||fuel.lastFluxQuantity()==0)){for(var stream:streams)for(var node:stream.nodes(field,false))if(node!=null)remove.add(node.pos);return remove;}
   if(column instanceof RbmkFluxColumn.Fuel fuel&&fuel.reasimFuel()&&(!fuel.hasFuelRod()||fuel.lastFluxQuantity()==0)){reasimNodes().forEachRemaining(pos->{if(pos!=null)remove.add(pos);});return remove;}
   boolean hasRod=false;var iterator=reasimNodes();while(iterator.hasNext()){var pos=iterator.next();if(pos==null)continue;var node=field.nodes.get(pos);if(node!=null&&node.column instanceof RbmkFluxColumn.Fuel fuel&&fuel.hasFuelRod()&&fuel.lastFluxQuantity()>0){hasRod=true;break;}}if(!hasRod){remove.add(pos);return remove;}for(var stream:streams)for(var node:stream.nodes(field,false))if(node!=null&&node.column instanceof RbmkFluxColumn.Fuel)return remove;remove.add(pos);return remove;
  }
 }
 public static final class Stream {
  private final Node origin;public final Vec3 vector;public double fluxQuantity,fluxRatio;private Stream(Node origin,Vec3 vector,double quantity,double ratio){this.origin=origin;this.vector=vector;fluxQuantity=quantity;fluxRatio=ratio;}
  private BlockPos point(int index){return origin.pos.offset((int)Math.floor(.5+vector.x*index),0,(int)Math.floor(.5+vector.z*index));}
  private Node[] nodes(Field field,boolean add){var nodes=new Node[fluxRange];var world=(ServerLevel)origin.column.entity().getLevel();for(int i=1;i<=fluxRange;i++){var pos=point(i);var node=field.nodes.get(pos);if(node!=null)nodes[i-1]=node;else{var column=column(world,pos);if(column!=null){node=make(field,column);nodes[i-1]=node;if(add)field.nodes.put(node.pos,node);}}}return nodes;}
  private void run(ServerLevel world,Field field){if(fluxQuantity==0)return;var pos=origin.pos;RbmkFluxColumn originColumn;var originNode=field.nodes.get(pos);if(originNode!=null)originColumn=originNode.column;else{originColumn=column(world,pos);if(originColumn==null)return;field.nodes.put(pos,new Node(originColumn));}int moderatedCount=0;
   for(int i=1;i<=fluxRange;i++){var target=point(i);if(fluxQuantity==0)return;var node=field.nodes.get(target);if(node==null){var column=column(world,target);if(column!=null){node=make(field,column);field.nodes.put(node.pos,node);}else{int hits=hits(world,target);if(hits==columnHeight)return;else if(hits>0){irradiate(world,pos,hits);fluxQuantity*=1-(double)hits/columnHeight;continue;}else{irradiate(world,pos,0);continue;}}}
    var type=node.type;if(type==RbmkFluxColumn.Type.OTHER)continue;var column=node.column;if(!node.lid)HbmRadiation.incrementRad(world,target.getX(),target.getY(),target.getZ(),(float)(fluxQuantity*.05F));if(type==RbmkFluxColumn.Type.MODERATOR||column.isModerated()){moderatedCount++;moderate();}
    if(column instanceof RbmkFluxColumn.Receiver receiver){if(type==RbmkFluxColumn.Type.ROD){var fuel=(RbmkFluxColumn.Fuel)receiver;if(fuel.hasFuelRod()){fuel.receiveFlux(this);return;}}else if(type==RbmkFluxColumn.Type.OUTGASSER&&((RbmkFluxColumn.Outgasser)receiver).canProcess()){receiver.receiveFlux(this);return;}}
    else if(type==RbmkFluxColumn.Type.CONTROL_ROD){var control=(RbmkFluxColumn.Control)column;if(control.controlLevel()>0){fluxQuantity*=control.controlMultiplier();continue;}return;}
    else if(type==RbmkFluxColumn.Type.REFLECTOR){if(origin.column.isModerated())moderatedCount++;if(fluxRatio>0&&moderatedCount>0)for(int m=0;m<moderatedCount;m++)moderate();if(reflectorEfficiency!=1D){fluxQuantity*=reflectorEfficiency;continue;}((RbmkFluxColumn.Fuel)originColumn).receiveFlux(this);return;}
    else if(type==RbmkFluxColumn.Type.ABSORBER){((RbmkFluxColumn.Absorber)column).addHeat(RbmkDials.getAbsorberHeatConversion(world)*fluxQuantity);if(absorberEfficiency==1)return;fluxQuantity*=absorberEfficiency;}
   }
   var nodes=nodes(field,true);var last=nodes[nodes.length-1];if(last==null){irradiate(world,BlockPos.containing(origin.pos.getX()+vector.x,origin.pos.getY(),origin.pos.getZ()+vector.z));return;}if(last.type==RbmkFluxColumn.Type.CONTROL_ROD){var control=(RbmkFluxColumn.Control)last.column;if(control.controlMultiplier()>0){fluxQuantity*=control.controlMultiplier();var after=BlockPos.containing(last.pos.getX()+vector.x,last.pos.getY(),last.pos.getZ()+vector.z);if(field.nodes.get(pos)==null){var column=column(world,after);if(column!=null){var node=make(field,column);field.nodes.put(node.pos,node);}else irradiate(world,after);}}}
  }
  private int hits(ServerLevel world,BlockPos pos){int count=0;for(int y=0;y<columnHeight;y++){var target=pos.above(y);var state=world.getBlockState(target);if(state.getBlock() instanceof RbmkColumnBlock||state.isSolidRender(world,target))count++;}return count;}
  private void irradiate(ServerLevel world,BlockPos pos){irradiate(world,pos,hits(world,pos));}private void irradiate(ServerLevel world,BlockPos pos,int hits){HbmRadiation.incrementRad(world,pos.getX(),pos.getY(),pos.getZ(),(float)(fluxQuantity*.05F*(1-(double)hits/columnHeight)));}public void moderate(){fluxRatio*=1-moderatorEfficiency;}
 }
 private RbmkNeutronField(){}
}
